        private static void doEcoute(Object data) {
            // thread for listening to customer requests
            try {
                // create the service
                service = new TcpListener(IPAddress.Any, port);
                 // launch it
                service.Start();
                // the server is active
                actif = true;
                 // follow-up
                Console.WriteLine("Serveur de calcul d'impôt lancé sur le port {0}", port);
                 // customer service loop
                TcpClient tcpClient = null;
                 // customer no
                int numClient = 0;
                 // endless loop
                while (true) {
                    // waiting for a customer
                    tcpClient = service.AcceptTcpClient();
                    // the service is provided by another task
                    ThreadPool.QueueUserWorkItem(doService, new Client() { CanalTcp = tcpClient, NumClient = numClient });
                     // next customer
                    numClient++;
                }
            } catch (Exception ex) {
                // we report the error
                Console.WriteLine("L'erreur suivante s'est produite sur le serveur : {0}", ex.Message);
            }
        }

         // customer info
        internal class Client {
             public TcpClient CanalTcp { get; set        ; } // customer liaison
             public int NumClient { get; set            ; } // customer no
}
</code></pre> <p>Este código é semelhante ao do servidor echo estudado no parágrafo 11.6.1. Apenas comentamos o que é diferente:</p> <ul> <li>linha 7: serviço de escuta iniciado   </li> <li>linha 9: indica que o serviço está agora ativo   </li> </ul> <p>Linha 21: os clientes são atendidos por threads de serviço que executam o método doService a seguir:</p> <pre><code>
private static void doService(Object infos) {
            // the customer is picked up and served
            Client client = infos as Client;
            // renders service to the customer
            Console.WriteLine("Début du service au client {0}", client.NumClient);
             // operation link TcpClient
            try {
                using (TcpClient tcpClient = client.CanalTcp) {
                    using (NetworkStream networkStream = tcpClient.GetStream()) {
                        using (StreamReader reader = new StreamReader(networkStream)) {
                            using (StreamWriter writer = new StreamWriter(networkStream)) {
                                 // unbuffered output stream
                                writer.AutoFlush = true;
                                // send a welcome message to the customer
                                writer.WriteLine("Bienvenue sur le serveur de calcul de l'impôt");
                                // loop read request/write response
                                string demande = null;
                                bool serviceFini = false;
                                while (!serviceFini &amp;&amp; (demande = reader.ReadLine()) != null) {
                                     // console monitoring
                                    if (echo) {
                                        Console.WriteLine("&lt;--- Client {0} : {1}", client.NumClient, demande);
                                    }
                                     // demand analysis
                                    demande = demande.Trim().ToLower();
                                    // empty request?
                                    if (demande.Length == 0) {
                                        // erroneous request
                                        writeClient(writer,client.NumClient,"Commande non reconnue. Utilisez la commande aide.");
                                        return;
                                    }

                                    // demand is broken down into fields
                                    string[] champs = Regex.Split(demande, @"\s+");
                                     // analysis
                                    switch (champs[0].ToLower()) {
                                        case "aide":
                                            writeClient(writer, client.NumClient, "Commandes acceptées\n1-aide\n2-impot marié(O/N) nbEnfants salaireAnnuel\n3-aurevoir");
                                            break;
                                        case "impot":
                                            // tax calculation
                                            writeClient(writer, client.NumClient, calculImpot(writer, client.NumClient, champs));
                                            break;
                                        case "aurevoir":
                                            serviceFini = true;
                                            writeClient(writer, client.NumClient, "Au revoir...");
                                            break;
                                        default:
                                            writeClient(writer, client.NumClient, "Commande non reconnue. Utilisez la commande aide.");
                                            break;
                                    }
                                }
                            }
                        }
                    }
                }
            } catch (Exception e) {
                // error
                Console.WriteLine("L'erreur suivante s'est produite lors du service au client {0} : {1}", client.NumClient, e.Message);
            } finally {
                Console.WriteLine("Fin du service au client {0}", client.NumClient);
            }
        }

        private static void writeClient(StreamWriter writer, int numClient, string message) {
             // echo console ?
            if (echo) {
                Console.WriteLine("---&gt; Client {0} : {1}", numClient, message);
            }
             // send msg to customer
            writer.WriteLine(message);
}
</code></pre> <p>Mais uma vez, o código é semelhante ao do servidor echo estudado no parágrafo 11.6.1. Apenas comentamos o que é diferente:</p> <ul> <li>linha 15: assim que o cliente se liga, o servidor envia uma mensagem de boas-vindas.   </li> <li>linhas 19-52: o ciclo para ler os comandos do cliente. O ciclo termina quando o cliente envia o «adeus».   </li> <li>linha 27: caso de um pedido vazio   </li> <li>linha 34: o pedido é dividido em campos para análise   </li> <li>linha 37: ajuda sobre pedidos: o cliente solicita uma lista de pedidos autorizados   </li> <li>linha 40: imposto do pedido: o cliente solicita um cálculo de imposto. Respondemos com a mensagem devolvida pelo calculImpot, que iremos detalhar em breve.   </li> <li>linha 44: despedida do pedido: o cliente indica que terminou.   </li> <li>linha 45: estamos a preparar-nos para sair do ciclo de leitura dos pedidos do cliente (linhas 19-52)   </li> <li>linha 46: respondemos ao cliente com uma mensagem de despedida   </li> <li>linha 48: uma encomenda incorreta. É enviada uma mensagem de erro ao cliente.   </li> </ul> <p>O cálculo dos impostos sobre o processamento da encomenda é assegurado pelo calculImpot a seguir:</p> <pre><code>
private static string calculImpot(StreamWriter writer, int numClient, string[] champs) {
             // request calculation married(Y/N) nbEnfants salaireAnnuel
             // 4 fields are required
            if (champs.Length != 4) {
                return "Commande calcul incorrecte. Utilisez la commande aide.";
            }
             // fields [1]
            string marié = champs[1];
            if (marié != "o" &amp;&amp; marié != "n") {
                return "Commande calcul incorrecte. Utilisez la commande aide.";
            }
             // fields [2]
            int nbEnfants;
            if (!int.TryParse(champs[2], out nbEnfants)) {
                return "Commande calcul incorrecte. Utilisez la commande aide.";
            }
             // fields [3]
            int salaireAnnuel;
            if (!int.TryParse(champs[3], out salaireAnnuel)) {
                return "Commande calcul incorrecte. Utilisez la commande aide.";
            }
             // that's it - tax calculation
            int impot = 0;
            try {
                impot = metier.CalculerImpot(marié == "o", nbEnfants, salaireAnnuel);
                return impot.ToString();
            } catch (Exception ex) {
                return ex.Message;
            }
        }
</code></pre> <ul> <li>linha 1: o método recebe a matriz de campos de comando como terceiro parâmetro tax. Se formulado corretamente, tem o formato married tax nbEnfants salaireAnnuel. O resultado do método é a resposta a enviar ao cliente.   </li> <li>linha 4: verifique se o comando tem 4 campos   </li> <li>linha 8: verificar se o campo married é válido   </li> <li>linha 14: verificar se o nbEnfants é válido   </li> <li>linha 19: verificar se o salaireAnnuel é válido   </li> <li>linha 25: o imposto é calculado utilizando o CalculerImpot da camada [metier]. Lembre-se de que esta camada está encapsulada numa DLL.   </li> <li>linha 26: se a camada [metier] tiver devolvido um resultado, este é devolvido ao cliente.   </li> <li>linha 28: se a camada [metier] tiver lançado uma exceção, a mensagem de exceção é devolvida ao cliente.   </li> </ul> <p></p>
